static int fail_count;
#define EXPECT(c,m) do { if (!(c)) { printf("FAIL: %s\n",m); fail_count++; } } while(0)
static int external_clock;
static double next_tick, next_event;
static void tick_ms(unsigned n) {
 while(n--) {
  while(external_clock && next_event <= now_ms) {
   while(next_tick <= next_event) {
    min_q[mi_w++ % MQ]=0x0fu | (uint32_t)0xf8u << 8;
    next_tick += 60000.0/120.0/24.0;
   }
   next_event += 11.0; /* BLE-style batches, as maintained rec_live_test models. */
  }
  run_ms(1);
 }
}
static void button(int b, int down) {
 if(down) held_btn |= 1u<<b; else held_btn &= ~(1u<<b);
 tick_ms(1);
}
static void key_edge(int k,int down) {
 if(down) held_keys |= 1u<<k; else held_keys &= ~(1u<<k);
 tick_ms(1);
}
static void target_step(int step) {
 unsigned guard=0;
 while(eng_step[TRK_BASS0] == step && guard++ <10000) tick_ms(1);
 while(eng_step[TRK_BASS0] != step && guard++ <10000) tick_ms(1);
 EXPECT(guard<10000,"real sequencer reaches requested recording cell");
 tick_ms(10);
}
typedef struct { bpart_t line; int gate_ms; uint32_t bytes,pcm_hash; float peak; } take_t;
static FILE *probe_tmp(void) {
 char path[]="build/host/rec-duration.XXXXXX"; int fd=mkstemp(path); FILE *f;
 if(fd<0) {perror("probe mkstemp");exit(2);}
 f=fdopen(fd,"w+");unlink(path);if(!f) {perror("probe fdopen");exit(2);}
 return f;
}
static uint32_t file_hash(FILE *f,uint32_t *bytes) {
 uint32_t h=2166136261u,n=0; int c;
 fflush(f); rewind(f); while((c=fgetc(f))!=EOF) { h=(h^(unsigned)c)*16777619u;n++; }
 *bytes=n; return h;
}
static take_t record_take(unsigned held_ms,int jitter) {
 take_t r; bpart_t *bp; char row[128]; unsigned t; int st,n,v,on=-1;
 external_clock=0; held_btn=held_keys=0; mi_r=mi_w=0;
 boot(); tick_ms(300);
 ui.part=PART_303A;set_view(V_SEQ);build_pages();
 bp=&cur_pat()->bass[0]; bp->len=16; memset(bp->step,0,sizeof bp->step);
 seq.bpm=120.0f; seq.clk_src=SEQ_CLK_INT;seq.send_notes=1;
 seq.mute=0;
 if(jitter) {seq.clk_src=SEQ_CLK_AUTO;external_clock=1;next_tick=now_ms;next_event=now_ms;}
 button(B_REC,1);button(B_REC,0);button(B_PLAY,1);button(B_PLAY,0);tick_ms(10);
 EXPECT(ui.rec && seq.playing,"actual REC/PLAY buttons enable live recording");
 target_step(4);key_edge(10,1);tick_ms(held_ms);key_edge(10,0);
 EXPECT(!kbd_held_note[0],"actual release clears live owner");
 button(B_PLAY,1);button(B_PLAY,0);button(B_REC,1);button(B_REC,0);tick_ms(400);
 r.line=*bp; r.gate_ms=-1;
 EXPECT(bstep_gate(&bp->step[4])==G_NOTE,"actual key press stores onset in expected cell");
 midi_log=probe_tmp();wav=probe_tmp();wav_frames=0;peak_out=0;
 button(B_PLAY,1);button(B_PLAY,0);tick_ms(2100);
 r.peak=peak_out;r.pcm_hash=file_hash(wav,&r.bytes);fclose(wav);wav=0;
 fflush(midi_log);rewind(midi_log);
 while(fgets(row,sizeof row,midi_log)) {
  if(sscanf(row,"%u ms: %x %x %x",&t,&st,&n,&v)!=4 || n!=kbd_note(10)) continue;
  if((st&0xf0)==0x90 && v && on<0)on=(int)t;
  else if(((st&0xf0)==0x80 || ((st&0xf0)==0x90&&!v)) && on>=0) {r.gate_ms=(int)t-on;break;}
 }
 fclose(midi_log);midi_log=0;
 button(B_PLAY,1);button(B_PLAY,0);tick_ms(400);
 printf("take clock=%s held=%u ms: replay_gate=%d ms, PCMbytes=%u hash=%08x peak=%f, cell4 note=%u flags=%u\n",jitter?"BLE-jitter":"internal",held_ms,r.gate_ms,r.bytes,r.pcm_hash,(double)r.peak,r.line.step[4].note,r.line.step[4].flags);
 EXPECT(r.gate_ms>0,"production MIDI sink emits replayed NoteOn/NoteOff pair");
 EXPECT(abs(r.gate_ms-(int)(held_ms+10))<=25,"actual release is preserved within endpoint/block/BLE batching resolution");
 EXPECT(r.bytes>300000 && r.peak>0.000001f,"production PCM replay contains rendered nonzero audio");
 return r;
}
int main(void) {
 take_t short_take,long_take; int jitter;
 load_force=0; /* Host wall time is not device CPU load; mirrors intended test-run setting. */
 for(jitter=0;jitter<2;jitter++) {
 short_take=record_take(30,jitter);long_take=record_take(300,jitter);
 EXPECT(memcmp(&short_take.line,&long_take.line,sizeof short_take.line)!=0,"different real held durations must survive into recorded pattern data");
 EXPECT(long_take.gate_ms-short_take.gate_ms>=200,"replay must preserve materially longer held-note duration instead of a fixed gate");
 }
 printf("rec_held_duration: %s\n",fail_count?"FAIL_BEFORE_FIX":"PASS");
 return fail_count!=0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Native-only adversarial whole-BREAK renderer: deterministic transport, macro
 * key-up (not MIDI routing), pitch, phase, bank replacement and voice retrigger.
 * Compare byte-exact trace to an independently compiled NIGHTLY baseline.
 * No physical device, ISR timing, host audio callback or target build claim. */
#define _POSIX_C_SOURCE 200809L
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "firmware/src/dsp/breaks.h"

static uint32_t rng(uint32_t *p) { uint32_t x=*p; x^=x<<13; x^=x>>17; x^=x<<5; return *p=x; }
static uint64_t frames, audible, zeros_after_stop;
static int failures;

static void render_checked(breaks_t *b, int blocks, FILE *f, int after_stop)
{
    float v[256];
    for (int j=0;j<blocks;j++) {
        breaks_render(b,v,256);
        for (unsigned i=0;i<256;i++) {
            uint32_t bits;
            if (!isfinite(v[i]) || fabsf(v[i]) > 2.0f) {
                if (failures++ < 5) fprintf(stderr,"invalid PCM sample=%g frame=%llu\n",v[i],(unsigned long long)frames);
            }
            if (v[i]!=0.0f) audible++;
            if (after_stop && v[i]==0.0f) zeros_after_stop++;
            memcpy(&bits,&v[i],sizeof bits);
            if (fwrite(&bits,sizeof bits,1,f)!=1) {perror("trace");exit(3);}
            frames++;
        }
    }
}

static void scenario(uint32_t n, uint32_t salt, FILE *f)
{
    uint32_t n2=n >= 72u ? n-7u : n+7u;
    size_t a_bytes=(n+1u)/2u,b_bytes=(n2+1u)/2u;
    uint8_t *a=malloc(a_bytes),*alt=malloc(b_bytes);
    breaks_t *b=calloc(1,sizeof(*b));
    if (!a || !alt || !b) {fputs("allocation failed\n",stderr);exit(3);}
    uint32_t seed=salt ^ n;
    for(size_t i=0;i<a_bytes;i++)a[i]=(uint8_t)rng(&seed);
    for(size_t i=0;i<b_bytes;i++)alt[i]=(uint8_t)rng(&seed);
    brk_loop_t la={.adpcm=a,.nsamples=n,.rate=44100,.bars=1};
    brk_loop_t lb={.adpcm=alt,.nsamples=n2,.rate=22050,.bars=2};
    breaks_init(b);
    breaks_set_loop(b,0,&la);
    breaks_set_loop(b,1,&lb);
    if (!b->bank[0].valid || !b->bank[1].valid) {fputs("bad bank\n",stderr);exit(1);}
    breaks_set(b,BRK_LEVEL,119);
    breaks_set(b,BRK_BCHANCE,73);
    breaks_set(b,BRK_COMPLEX,43);
    breaks_set(b,BRK_ROLL,18);
    uint16_t held=0;
    for(int step=0;step<64;step++) {
        uint32_t x=rng(&seed);
        int key=(int)((x>>13)%11u);
        uint16_t bit=(uint16_t)(1u<<key);
        held^=bit;
        breaks_live(b,key,(held&bit)!=0);
        if ((step%3)==0) breaks_set(b,BRK_PITCH,6+(int)(x%13u));
        if ((step%5)==1) breaks_pin(b,(int)((x>>19)&7u));
        if ((step%7)==4) breaks_set(b,BRK_ROLL,(int)((x>>9)%101u));
        if ((step%11)==8) breaks_set_loop(b,step&1?0:1,step&1?&la:&lb);
        if ((step%13)==7) breaks_set_quiet(b,1);
        if ((step%13)==9) breaks_set_quiet(b,0);
        if (step==25 || step==49) breaks_stop(b);
        breaks_step(b,step%16,step/16,256.0f+(float)((x>>7)%8000u), (x&7u)!=0);
        render_checked(b,7,f,0);
    }
    /* Release every live key; turn off sound, stop and drain release/quiet tail. */
    for (int key=0;key<=10;key++)breaks_live(b,key,0);
    breaks_stop(b);
    breaks_set_quiet(b,1);
    render_checked(b,8,f,1);
    if (!breaks_silent(b)) {
        if (failures++ < 5) fprintf(stderr,"post-stop not silent n=%u\n",n);
    }
    free(b);free(alt);free(a);
}

int main(int argc, char **argv)
{
    if(argc!=3 || strcmp(argv[1],"--trace")){
        fputs("usage: breaks_renderer_adversarial_test --trace output.pcm\n",stderr);
        return 2;
    }
    FILE *f=fopen(argv[2],"wb");
    if(!f){perror(argv[2]);return 3;}
    static const uint32_t lens[]={64,65,511,512,513,1024,4096,176400,705600,2116800};
    for(unsigned i=0;i<sizeof lens/sizeof lens[0];i++){
        scenario(lens[i],0x35483247u+i*9187u,f);
        scenario(lens[i],0x92713441u+i*3371u,f);
    }
    if(fclose(f)){perror("close");return 3;}
    printf("ADVERSARIAL_TRACE scenarios=%zu frames=%llu audible=%llu zeros_after_stop=%llu failures=%d\n",
           sizeof lens/sizeof lens[0]*2,(unsigned long long)frames,(unsigned long long)audible,
           (unsigned long long)zeros_after_stop,failures);
    if(!audible || !zeros_after_stop || failures) return 1;
    return 0;
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Exact-blob NIGHTLY vs PR93 BREAK at musical/sensible accelerated rates.

The source projections must come from the named Git revisions. The IMA counter
is inserted in a throwaway copy of the identical GPL header for both builds.
Test speeds/lengths are projected only in scratch after original Git-blob checks.
This is producer evidence, not independent QA or microcontroller timing.
"""
import argparse
import hashlib
import json
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile

COMMON = {
    'firmware/src/dsp/ima_adpcm.h': '9ba16e4fe9f0cb643c95a68d540042ab2581d4de',
    'firmware/src/dsp/fastmath.h': '7d2e41bf70590bafa8af0a7376bb912bf763b098',
    'firmware/src/dsp/x0x_param.h': 'f7c9bf22b0606946905790dc20497a2e4b2cb4a6',
    'firmware/src/seq/pattern.h': '9a0703418aae95b14f1b70905cfac916da38d7dd',
}
RENDERERS = {
    'nightly': {
        'firmware/src/dsp/breaks.c': '1d3d692b6788d9d1f13901cd7ab13df506cdb72f',
        'firmware/src/dsp/breaks.h': '094af6650333e844311a8806145a6177a0318225',
    },
    'pr93': {
        'firmware/src/dsp/breaks.c': '9e1e607e2ddc3028383bfb6ebc85fbc7ac6864c5',
        'firmware/src/dsp/breaks.h': '6cb71d336c2c90fdc60a9594c2356f3a4379c264',
    },
}
TEST = 'tests/host/breaks_reverse_fast_advance_test.c'
TEST_BLOB = '5e77b152253422d36ab7218669187d02318d21cb'
ORIGINAL_RATES = 'const int rates[]={16,31,32,33,64,257,4096};'
MUSICAL_RATES = 'const int rates[]={1,2,3,4,6,8,12};'
ORIGINAL_SIZES = 'const uint32_t sizes[]={64,65,255,4097,176400};'
LONG_SIZES = 'const uint32_t sizes[]={64,65,255,4097,176400,705600,1411200};'
FUNC = 'static inline int32_t ima_decode(const uint8_t *d, uint32_t i, int32_t *pred, int32_t *idx)\n{'


def blob(data):
    return hashlib.sha1(b'blob ' + str(len(data)).encode() + b'\0' + data).hexdigest()


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def invoke(args, log):
    p = subprocess.run(args, capture_output=True, text=True, timeout=150, check=False)
    log.write_text('$ ' + ' '.join(map(str, args)) + '\nexit=' + str(p.returncode) +
                   '\nSTDOUT:\n' + p.stdout + '\nSTDERR:\n' + p.stderr)
    return p.returncode, p.stdout


def rows(log):
    result = {}
    for line in log.splitlines():
        if not line.startswith('n='):
            raise RuntimeError('unexpected runner output: ' + line[:80])
        d = dict(part.split('=', 1) for part in line.split())
        key = (int(d['n']), d['direction'], int(d['rate']), int(d['trial']))
        if key in result or int(d['audible']) < 1 or d['stopped'] != '1':
            raise RuntimeError('duplicate, silent, or unstopped case: ' + str(key))
        result[key] = {k: int(d[k]) for k in ('setup', 'decodes', 'max', 'p95', 'p99', 'audible')}
        result[key]['pcm'] = d['pcm']
        if not 0 <= result[key]['p95'] <= result[key]['p99'] <= result[key]['max']:
            raise RuntimeError('invalid per-block order: ' + str(key))
    if len(result) != 196:
        raise RuntimeError('expected 196 exact workload cases, received ' + str(len(result)))
    return result


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--nightly-root', required=True, type=Path)
    p.add_argument('--pr93-root', required=True, type=Path)
    p.add_argument('--output-dir', required=True, type=Path)
    a = p.parse_args()
    if a.output_dir.exists():
        p.error('refusing to overwrite an existing output directory')
    roots = {'nightly': a.nightly_root.resolve(), 'pr93': a.pr93_root.resolve()}
    pins = {}
    for kind in roots:
        pins[kind] = {}
        for name, expected in {**COMMON, **RENDERERS[kind], **({TEST: TEST_BLOB} if kind == 'pr93' else {})}.items():
            actual = blob((roots[kind] / name).read_bytes())
            if actual != expected:
                raise RuntimeError(f'{kind} invalid Git blob {name}: {actual} != {expected}')
            pins[kind][name] = actual
    a.output_dir.mkdir(parents=True, exist_ok=False)
    found = {}
    with tempfile.TemporaryDirectory(prefix='break-nightly-pr93-') as td:
        tmp = Path(td)
        for kind, root in roots.items():
            work = tmp / kind
            for name in pins[kind]:
                to = work / name
                to.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(root / name, to)
            if kind == 'nightly':
                test_to = work / TEST
                test_to.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(roots['pr93'] / TEST, test_to)
            # Only change the pinned fixture's host rate set in a scratch copy.
            # Both implementations receive the exact same stimulus.
            test_to = work / TEST
            fixture = test_to.read_text()
            if fixture.count(ORIGINAL_RATES) != 1 or fixture.count(ORIGINAL_SIZES) != 1:
                raise RuntimeError('pinned fixture rate syntax mismatch')
            test_to.write_text(fixture.replace(ORIGINAL_RATES, MUSICAL_RATES).replace(ORIGINAL_SIZES, LONG_SIZES))
            header = work / 'firmware/src/dsp/ima_adpcm.h'
            s = header.read_text()
            if s.count(FUNC) != 1 or s.count('#include <stdint.h>') != 1:
                raise RuntimeError('unexpected IMA header instrumentation location')
            s = s.replace('#include <stdint.h>', '#include <stdint.h>\nextern volatile uint64_t x0x_host_ima_decode_calls;')
            header.write_text(s.replace(FUNC, FUNC + '\n    ++x0x_host_ima_decode_calls;'))
            for compiler in ('gcc', 'clang'):
                tag = compiler + '-' + kind
                binary = work / tag
                command = [compiler, '-std=c11', '-O2', '-Wall', '-Wextra', '-Werror',
                           '-pedantic', '-ffp-contract=off', '-I' + str(work),
                           str(work / TEST), str(work / 'firmware/src/dsp/breaks.c'),
                           '-lm', '-o', str(binary)]
                ec, _ = invoke(command, a.output_dir / (tag + '-compile.log'))
                if ec:
                    raise RuntimeError(tag + ' compile exit ' + str(ec))
                trace = a.output_dir / (tag + '.pcm')
                ec, stdout = invoke([str(binary), '--check', '--trace', str(trace)],
                                    a.output_dir / (tag + '-run.log'))
                if ec:
                    raise RuntimeError(tag + ' run exit ' + str(ec))
                ec, _ = invoke([str(binary)], a.output_dir / (tag + '-negative.log'))
                if ec != 2:
                    raise RuntimeError(tag + ' invalid-argument exit ' + str(ec) + ' != 2')
                if trace.stat().st_size != 196 * 8 * 64 * 4:
                    raise RuntimeError(tag + ' unexpected trace size')
                found[tag] = {'cases': rows(stdout), 'pcm_sha256': sha(trace),
                              'trace_bytes': trace.stat().st_size}
                trace.unlink()  # no synthetic PCM distribution
    comparisons = {}
    for compiler in ('gcc', 'clang'):
        old = found[compiler + '-nightly']; new = found[compiler + '-pr93']
        if old['pcm_sha256'] != new['pcm_sha256'] or old['cases'].keys() != new['cases'].keys():
            raise RuntimeError('NIGHTLY vs PR93 whole-trace or scenario mismatch: ' + compiler)
        if any(old['cases'][k]['pcm'] != new['cases'][k]['pcm'] or
               old['cases'][k]['audible'] != new['cases'][k]['audible'] for k in old['cases']):
            raise RuntimeError('PCM/control mismatch: ' + compiler)
        stats = {}
        for direction in ('R', 'F'):
            ks = [k for k in old['cases'] if k[1] == direction]
            before = sum(old['cases'][k]['decodes'] for k in ks)
            after = sum(new['cases'][k]['decodes'] for k in ks)
            if any(new['cases'][k]['decodes'] > old['cases'][k]['decodes'] for k in ks):
                raise RuntimeError('unexpected increased decoder work: ' + direction)
            stats[direction] = {'cases': len(ks), 'baseline_decodes': before,
                                'candidate_decodes': after,
                                'reduction_percent': round(100 * (before - after) / before, 4),
                                'baseline_max_block': max(old['cases'][k]['max'] for k in ks),
                                'candidate_max_block': max(new['cases'][k]['max'] for k in ks)}
            # Show whether users actually benefit at 1-4x, not just at exotic 257x.
            rate_stats = {}
            for rate in (1, 2, 3, 4, 6, 8, 12):
                matching = [k for k in ks if k[2] == rate]
                bsum = sum(old['cases'][k]['decodes'] for k in matching)
                csum = sum(new['cases'][k]['decodes'] for k in matching)
                rate_stats[str(rate)] = {'baseline_decodes': bsum, 'candidate_decodes': csum,
                                         'reduction_percent': round(100 * (bsum - csum) / bsum, 4)}
            stats[direction]['by_speed'] = rate_stats
            matching = [k for k in ks if k[2] in (1, 2, 3, 4)]
            bsum = sum(old['cases'][k]['decodes'] for k in matching)
            csum = sum(new['cases'][k]['decodes'] for k in matching)
            stats[direction]['rates_1_to_4'] = {'baseline_decodes': bsum, 'candidate_decodes': csum,
                 'reduction_percent': round(100 * (bsum - csum) / bsum, 4)}
        comparisons[compiler] = {'trace_sha256': old['pcm_sha256'], 'stats': stats}
    if comparisons['gcc']['trace_sha256'] != comparisons['clang']['trace_sha256']:
        raise RuntimeError('compiler PCM mismatch')
    report = {'revision': 'performance-pr93-musical-speed-source-compare-20261025-r21',
              'producer_only': True, 'firmware_compiler_inputs_modified': False,
              'baseline_nightly_commit': '54f2ffbc3124f7449a69067dc8215a2d91a2e675',
              'candidate_pr93_commit': '60db12d6d76b8e6707d61df8deeee01296edf393',
              'candidate_firmware_tree': 'ee863f9cba6cbfb4e471d199ae408c7694acbac5',
              'pins': pins, 'scratch_rates': [1, 2, 3, 4, 6, 8, 12], 'scratch_lengths': [64, 65, 255, 4097, 176400, 705600, 1411200], 'results': comparisons,
              'source_kind': 'exact-blob C/H/dependencies and pinned C fixture; scratch-only identical lower-rate stimulus; not full repo root build',
              'known_failure': 'original unmodified PR93 fastmath.h UBSan FAIL; PR28 owns',
              'gates': {'independent_QA': 'NOT_RUN', 'Elite_Pro_target_BUILD_ONLY': 'NOT_RUN',
                        'hardware': 'NOT_RUN', 'publication': 'NOT_RUN'}}
    (a.output_dir / 'result.json').write_text(json.dumps(report, sort_keys=True, indent=2) + '\n')
    print('PASS scoped NIGHTLY vs PR93 musical-rate PCM equivalence')
    print(json.dumps(comparisons, sort_keys=True, indent=2))


if __name__ == '__main__':
    try:
        main()
    except (OSError, RuntimeError, subprocess.TimeoutExpired, ValueError) as ex:
        print('FAIL:', ex, file=sys.stderr)
        sys.exit(1)

