/* SPDX-License-Identifier: GPL-3.0-only
 * BF-028: a skipped 303 note is a rest on BOTH the audio and MIDI sink.
 * Real sequencer entry points and an adversarial bass callback exercise the
 * same acceptance boundary as engine.c's T_PROB callback.
 */
#include <stdio.h>
#include <string.h>
#include "../../firmware/src/seq/sequencer.h"

static int fails, midi_on[128], midi_off[128], on_count, off_count;
static int allow[128], received_slide[128];
#define CHECK(x, msg) do { if (!(x)) { fprintf(stderr, "FAIL: %s\n", msg); fails++; } } while (0)

static void bass_off(void *ctx, int p);
static int drum(void *ctx, int k, int v, float velocity)
{ (void)ctx; (void)k; (void)v; (void)velocity; return 1; }
/* A zero return means the engine's probability rejected the note. */
#ifdef BF028_BASELINE
static void bass_on(void *ctx, int part, int note, int accent, int slide, int velocity)
#else
static int bass_on(void *ctx, int part, int note, int accent, int slide, int velocity)
#endif
{
    (void)ctx; (void)part; (void)accent; (void)velocity;
    received_slide[note] = slide;
    on_count++;
#ifdef BF028_BASELINE
    if (!allow[note]) bass_off(ctx, part);
#else
    return allow[note];
#endif
}
static void bass_off(void *ctx, int p) { (void)ctx; (void)p; off_count++; }
static void brk(void *ctx, int step, int bar, float t, int en)
{ (void)ctx; (void)step; (void)bar; (void)t; (void)en; }
static void brk_stop(void *ctx) { (void)ctx; }
static void midi(void *ctx, uint8_t st, uint8_t d1, uint8_t d2)
{
    (void)ctx; (void)d2;
    if ((st & 15u) != 1u) return; /* the 303 A's default channel 2 */
    if ((st & 0xF0u) == 0x90u) midi_on[d1]++;
    if ((st & 0xF0u) == 0x80u) midi_off[d1]++;
}
static const seq_sink_t sink = {drum, bass_on, bass_off, brk, brk_stop, midi, 0, 0};
static seq_t seq;
static pattern_t patterns[NPAT];
static void reset(void)
{
    memset(midi_on, 0, sizeof midi_on);
    memset(midi_off, 0, sizeof midi_off);
    memset(allow, 0, sizeof allow);
    memset(received_slide, 0x7f, sizeof received_slide);
    on_count = off_count = 0;
    for (int i=0; i<NPAT; i++) pattern_init(&patterns[i], 100u + (uint32_t)i, 200u + (uint32_t)i);
    seq_init(&seq, patterns);
    seq.send_clock = 0;
    seq.send_notes = 1;
    seq.bpm = 120.0f;
    /* Every other part remains empty. */
    patterns[0].bass[0].len = 4;
}
static void advance_samples(uint32_t samples)
{
    while (samples) {
        uint32_t n = samples < 256u ? samples : 256u;
        seq_advance(&seq, 0, &sink);
        while (n) {
            uint32_t k = seq_until_event(&seq, n);
            if (!k || k > n) { fprintf(stderr,"invalid event advance %u/%u\n",k,n); fails++; return; }
            seq_advance(&seq, k, &sink);
            n -= k;
            samples -= k;
        }
    }
}
static void test_skipped_first_note(void)
{
    reset();
    patterns[0].bass[0].step[0] = (bstep_t){40, G_NOTE, 100};
    allow[40] = 0;
    seq_start(&seq);
    advance_samples(3);
    CHECK(on_count == 1, "probability callback reached for first step");
    CHECK(midi_on[40] == 0, "a rejected 303 step must have no external MIDI NoteOn");
    CHECK(!seq.bass_out_valid[0], "skipped note must not have an active MIDI voice");
    CHECK(!seq.t[TRK_BASS0].sounding, "rejected 303 note must not leave a phantom internal voice");
}
static void test_reject_after_audible_note(void)
{
    reset();
    patterns[0].bass[0].step[0] = (bstep_t){40, G_NOTE | BS_SLIDE, 100};
    patterns[0].bass[0].step[1] = (bstep_t){41, G_NOTE, 100};
    allow[40] = 1;
    allow[41] = 0;
    seq_start(&seq);
    advance_samples(3);
    CHECK(midi_on[40] == 1 && seq.bass_out_valid[0], "accepted step retains MIDI NoteOn");
    advance_samples(6000);
    CHECK(on_count == 2, "both bass steps reached the chance callback");
    CHECK(midi_on[41] == 0, "rejected slide target cannot produce MIDI NoteOn");
    CHECK(midi_off[40] == 1, "old external note ended on a skipped slide target");
    CHECK(!seq.bass_out_valid[0] && !seq.bass_slide_valid[0], "skipped slide target clears both tracked MIDI voices");
    CHECK(!seq.t[TRK_BASS0].sounding && !seq.t[TRK_BASS0].held_note && !seq.t[TRK_BASS0].to_off,
          "rejected slide target restores silent 303 sequencer state");
}
static void test_both_accepted(void)
{
    reset();
    patterns[0].bass[0].step[0] = (bstep_t){40, G_NOTE | BS_SLIDE, 100};
    patterns[0].bass[0].step[1] = (bstep_t){41, G_NOTE, 100};
    allow[40] = allow[41] = 1;
    seq_start(&seq);
    advance_samples(6003);
    CHECK(midi_on[40] == 1 && midi_on[41] == 1,
          "accepting both notes preserves existing external MIDI playback");
    CHECK(seq.bass_out_valid[0], "accepted second note is still tracked");
}
static void test_reject_then_clean_attack(void)
{
    reset();
    patterns[0].bass[0].step[0] = (bstep_t){40, G_NOTE, 100};
    patterns[0].bass[0].step[1] = (bstep_t){41, G_NOTE | BS_SLIDE, 100};
    patterns[0].bass[0].step[2] = (bstep_t){42, G_NOTE, 100};
    allow[40] = 1;
    allow[41] = 0;
    allow[42] = 1;
    seq_start(&seq);
    advance_samples(11500);
    CHECK(midi_on[40] == 1 && midi_on[41] == 0 && midi_on[42] == 1,
          "accepted 303 note after skipped slide is the only new MIDI voice");
    CHECK(received_slide[42] == 0,
          "accepted note after skipped slide starts with clean attack, not phantom glide");
}

static void test_live_rec_echo_survives(void)
{
    reset();
    patterns[0].bass[0].step[0] = (bstep_t){40, G_REST, 0};
    patterns[0].bass[0].step[1] = (bstep_t){41, G_NOTE, 108};
    allow[41] = 0;     /* must not consult probability: the key already played locally */
    seq_start(&seq);
    advance_samples(3);
    seq_rec_skip(&seq, TRK_BASS0, 1, 0);
    advance_samples(6000);
    CHECK(on_count == 0, "recorded live hit skips the internal replay callback");
    CHECK(midi_on[41] == 1, "recorded live 303 hit still echoes MIDI (REC-06)");
    CHECK(seq.bass_out_valid[0], "recorded live MIDI note remains tracked for its eventual NoteOff");
}

static void test_tie_after_rejection_is_silent(void)
{
    reset();
    patterns[0].bass[0].len = 4;
    patterns[0].bass[0].step[0] = (bstep_t){40, G_NOTE, 80};
    patterns[0].bass[0].step[1] = (bstep_t){45, G_TIE, 90};
    allow[40] = 0;
    allow[45] = 1;  /* acceptance of TIE must not revive a rejected NOTE */
    seq_start(&seq);
    advance_samples(6003);
    CHECK(midi_on[40] == 0 && midi_on[45] == 0,
          "a tie after a skipped 303 note cannot resurrect a MIDI voice");
    CHECK(on_count == 1, "orphan TIE never invokes a second onset callback");
    CHECK(!seq.t[TRK_BASS0].sounding, "orphan TIE preserves silent internal bass state");
    CHECK(!seq.bass_out_valid[0], "rejected note + tie leaves no stranded voice");
}


static void test_initial_tie_remains_silent(void)
{
    reset();
    patterns[0].bass[0].step[0] = (bstep_t){45, G_TIE, 100};
    allow[45] = 1;
    seq_start(&seq);
    advance_samples(3);
    CHECK(on_count == 0, "initial orphan TIE cannot create a bass onset");
    CHECK(midi_on[45] == 0, "initial orphan TIE cannot send MIDI NoteOn");
    CHECK(!seq.t[TRK_BASS0].sounding, "initial orphan TIE stays silent internally");
}
static void test_rest_tie_remains_silent(void)
{
    reset();
    patterns[0].bass[0].step[0] = (bstep_t){40, G_REST, 0};
    patterns[0].bass[0].step[1] = (bstep_t){45, G_TIE, 100};
    allow[45] = 1;
    seq_start(&seq);
    advance_samples(6003);
    CHECK(on_count == 0, "REST then TIE must not trigger any bass onset");
    CHECK(midi_on[45] == 0 && !seq.bass_out_valid[0],
          "REST then TIE must not claim a MIDI note");
}
static void test_valid_tie_sustains_only_previous_note(void)
{
    reset();
    patterns[0].bass[0].step[0] = (bstep_t){40, G_NOTE, 100};
    patterns[0].bass[0].step[1] = (bstep_t){45, G_TIE, 100};
    patterns[0].bass[0].step[2] = (bstep_t){42, G_REST, 0};
    allow[40] = allow[45] = 1;
    seq_start(&seq);
    advance_samples(6003);
    CHECK(on_count == 1, "valid NOTE-TIE has exactly one onset");
    CHECK(midi_on[40] == 1 && midi_on[45] == 0,
          "valid TIE sustains original MIDI pitch without retrigger");
    CHECK(seq.t[TRK_BASS0].sounding, "valid TIE keeps original 303 sounding");
    advance_samples(6000);
    CHECK(midi_off[40] == 1 && !seq.bass_out_valid[0],
          "REST after TIE releases held external note exactly once");
}
static void test_rejected_tie_then_ordinary_note(void)
{
    reset();
    patterns[0].bass[0].step[0] = (bstep_t){40, G_NOTE, 100};
    patterns[0].bass[0].step[1] = (bstep_t){45, G_TIE, 100};
    patterns[0].bass[0].step[2] = (bstep_t){42, G_NOTE, 100};
    allow[40] = 0;
    allow[45] = allow[42] = 1;
    seq_start(&seq);
    advance_samples(11500);
    CHECK(on_count == 2, "orphan TIE never invokes callback before later proper NOTE");
    CHECK(midi_on[45] == 0 && midi_on[42] == 1,
          "later accepted NOTE plays without resurrecting rejected TIE");
    CHECK(received_slide[42] == 0, "later accepted NOTE is a clean attack");
    CHECK(seq.t[TRK_BASS0].sounding, "later accepted NOTE remains audible");
}

int main(void)
{
    test_skipped_first_note();
    test_reject_after_audible_note();
    test_both_accepted();
    test_reject_then_clean_attack();
    test_live_rec_echo_survives();
    test_tie_after_rejection_is_silent();
    test_initial_tie_remains_silent();
    test_rest_tie_remains_silent();
    test_valid_tie_sustains_only_previous_note();
    test_rejected_tie_then_ordinary_note();
    if (fails) { printf("BF028: %d failed assertions\n", fails); return 1; }
    puts("BF028: 303 chance matches MIDI and local audio; good notes stay audible");
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Chicago AmpMod Env/Gate on native303: Gate holds VCA while the note is down; Env keeps
 * the Open303 amp path. Independent of EnvMod, FEnv, and velocity→cutoff. */
#include <math.h>
#include <stdio.h>
#include <string.h>
#include "bass303.h"

static int fails;
#define CHECK(c, ...) do { if (!(c)) { printf("FAIL " __VA_ARGS__); printf("\n"); fails++; } } while (0)

static float buf[44100];

static double rms_range(const float *x, int a, int b)
{
    double s = 0;
    int i, n = b - a;
    if (n <= 0)
        return 0;
    for (i = a; i < b; i++)
        s += (double)x[i] * (double)x[i];
    return sqrt(s / (double)n);
}

static void render_held(bass303_t *b, int mode, float *out, int n)
{
    int pos = 0;
    bass303_init(b);
    bass303_set(b, BASS303_CUTOFF, 64);
    bass303_set(b, BASS303_RESO, 0);
    bass303_set(b, BASS303_ENVMOD, 0);
    bass303_set(b, BASS303_FENV, 0);
    bass303_set(b, BASS303_AMPMODE, mode);
    bass303_set(b, BASS303_VOLUME, 96);
    bass303_set(b, BASS303_DRIVE, 0);
    bass303_note_on_velocity(b, 48, 0, 0, 100);
    while (pos < n) {
        int m = n - pos > 128 ? 128 : n - pos;
        bass303_render(b, out + pos, m);
        pos += m;
    }
}

static void test_param_surface(void)
{
    const x0x_param_t *p = bass303_param(BASS303_AMPMODE);
    CHECK(bass303_nparams() == BASS303_NPARAMS, "nparams includes AmpMod");
    CHECK(BASS303_AMPMODE == 16, "AmpMod index is 16 (after FEnv); sibling param ports use 17+");
    CHECK(p && p->max == 1 && p->def == BASS303_AMP_ENV, "AmpMod default Env");
    CHECK(p && p->names && !strcmp(p->names[0], "Env") && !strcmp(p->names[1], "Gate"),
          "AmpMod labels Env/Gate");
    CHECK(p && strcmp(p->name, "EnvMod") != 0 && strcmp(p->name, "FEnv") != 0,
          "AmpMod name is not EnvMod/FEnv");
}

static void test_gate_holds_env_falls(void)
{
    bass303_t env, gate;
    double e0, e1, g0, g1, env_drop_db, gate_drop_db;
    render_held(&env, BASS303_AMP_ENV, buf, 44100);
    CHECK(env.amp_y < 0.85f, "Env amp_y decays while held (got %g)", (double)env.amp_y);
    e0 = rms_range(buf, 2205, 4410);   /* ~50-100 ms */
    e1 = rms_range(buf, 17640, 19845); /* ~400-450 ms */
    render_held(&gate, BASS303_AMP_GATE, buf, 44100);
    CHECK(fabsf(gate.amp_y - 1.0f) < 1e-6f, "Gate amp_y holds at 1 while held (got %g)", (double)gate.amp_y);
    g0 = rms_range(buf, 2205, 4410);
    g1 = rms_range(buf, 17640, 19845);
    CHECK(e0 > 1e-6 && e1 > 1e-6 && g0 > 1e-6 && g1 > 1e-6, "both modes produce audio");
    env_drop_db = 20.0 * log10(e1 / e0);
    gate_drop_db = 20.0 * log10(g1 / g0);
    /* Filter EG can still move RMS under Gate (Chicago: ADSR still hits the filter). VCA hold is
     * the AmpMod contract; Gate RMS must fall less than Env. */
    CHECK(env_drop_db < -0.5, "Env output falls while held (got %.3f dB)", env_drop_db);
    CHECK(gate_drop_db > env_drop_db + 0.4, "Gate output falls less than Env (gate %.3f env %.3f)",
          gate_drop_db, env_drop_db);
}

static void test_gate_releases(void)
{
    bass303_t b;
    double mid, tail;
    int pos = 0;
    bass303_init(&b);
    bass303_set(&b, BASS303_AMPMODE, BASS303_AMP_GATE);
    bass303_set(&b, BASS303_VOLUME, 96);
    bass303_set(&b, BASS303_DRIVE, 0);
    bass303_note_on_velocity(&b, 48, 0, 0, 100);
    while (pos < 22050) {
        int m = 128;
        if (pos + m > 22050)
            m = 22050 - pos;
        bass303_render(&b, buf + pos, m);
        pos += m;
    }
    bass303_note_off(&b);
    while (pos < 44100) {
        int m = 128;
        if (pos + m > 44100)
            m = 44100 - pos;
        bass303_render(&b, buf + pos, m);
        pos += m;
    }
    mid = rms_range(buf, 11025, 16538);
    tail = rms_range(buf, 33075, 44100);
    CHECK(mid > 1e-4, "Gate sounds while held");
    CHECK(tail < mid * 0.05, "Gate releases after note-off");
}

static void test_env_matches_default_init(void)
{
    bass303_t a, b;
    float xa[256], xb[256];
    int i;
    bass303_init(&a);
    bass303_init(&b);
    CHECK(bass303_get(&a, BASS303_AMPMODE) == BASS303_AMP_ENV, "init AmpMod is Env");
    bass303_set(&b, BASS303_AMPMODE, BASS303_AMP_ENV);
    bass303_note_on_velocity(&a, 48, 0, 0, 100);
    bass303_note_on_velocity(&b, 48, 0, 0, 100);
    bass303_render(&a, xa, 256);
    bass303_render(&b, xb, 256);
    for (i = 0; i < 256; i++)
        if (xa[i] != xb[i])
            break;
    CHECK(i == 256, "explicit Env matches default AmpMod path bit-exact");
}

int main(void)
{
    fails = 0;
    test_param_surface();
    test_gate_holds_env_falls();
    test_gate_releases();
    test_env_matches_default_init();
    if (fails) {
        printf("%d FAIL\n", fails);
        return 1;
    }
    printf("bass303_ampmode: OK\n");
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Exercise real panel/SMC selection and REC actions, then record keyboard notes
 * through production UI into the selected pattern. Compare emitted Record
 * lamps with that destination. Radio, hardware I/O and unused clip handlers
 * are substitutes; no physical-device or audio result is claimed. */
#define main simulator_main
#include "../../host/x0x_host.c"
#undef main
#include <assert.h>

uint8_t smk_clip_mode_on(void) { return 0; }
int smk_ck_smc_turn(int n, int delta) { (void)n; (void)delta; return 0; }
int smk_ck_smc_nav(uint8_t note) { (void)note; return 0; }
static uint8_t wire_led[128];
int plat_ble_smc_send(const uint8_t *msg, uint8_t len)
{
    assert(len == 3);
    if (msg[0] == 0x90) wire_led[msg[1]] = msg[2];
    return 1;
}
#ifndef SMC_MIXER_SOURCE
#define SMC_MIXER_SOURCE "app/smc_mixer.c"
#endif
#include SMC_MIXER_SOURCE

static unsigned failures, writes, projections;

static void panel_input(void)
{
    now_ms++;
    input();
}

static void panel_button(int button)
{
    held_btn |= 1u << button;
    panel_input();
    held_btn &= ~(1u << button);
    panel_input();
}

static const int display_position[5] = {0,1,4,3,2};
static void panel_select(int part)
{
    for (int i = 0; ui.part != part && i < NPARTS; i++) {
        enc_acc[EN_ALGO] = display_position[ui.part] < display_position[part] ? 1 : -1;
        panel_input();
    }
    assert(ui.part == part);
}

static void smc_press(int note)
{
    const uint8_t down[3] = {0x90, (uint8_t)note, 127};
    const uint8_t up[3] = {0x80, (uint8_t)note, 0};
    smc_ble_midi(down, sizeof down);
    smc_ble_midi(up, sizeof up);
    smc_poll();
    assert((smc_rx_diag() >> 24) == 0);
}

static void record_feedback(const char *label)
{
    unsigned actual = 0;
    unsigned expected = ui.rec ? 1u << display_position[ui.part] : 0;
    smc_frame();
    for (int part = 0; part < NPARTS; part++) {
        assert(wire_led[part] == 0 || wire_led[part] == 127);
        if (wire_led[part]) actual |= 1u << part;
    }
    projections++;
    if (actual != expected || wire_led[0x5F] != (ui.rec ? 127 : 0)) {
        failures++;
        fprintf(stderr, "FAIL %s: selected part=%u REC=%u emitted strip mask=%u expected=%u global=%u\n",
                label, ui.part, ui.rec, actual, expected, wire_led[0x5F]);
    }
}

static void record_note(const char *label, int key)
{
    assert(ui.rec && is_303() && !seq.playing && ui.view == V_SEQ);
    int bass = bidx(), other = bass ^ 1;
    bpart_t *destination = &proj.pat[seq.ppat[ui.part]].bass[bass];
    bpart_t *untouched = &proj.pat[seq.ppat[PART_303A + other]].bass[other];
    bpart_t before_other = *untouched;
    int length = destination->len ? destination->len : 16;
    int step = ui.wpos[bass] % length;
    destination->step[step].note = 0;
    destination->step[step].flags = G_REST;
    held_keys |= 1u << key;
    panel_input();
    held_keys &= ~(1u << key);
    panel_input();
    assert(destination->step[step].note == kbd_note(key));
    assert(bstep_gate(&destination->step[step]) == G_NOTE);
    assert(ui.wpos[bass] == (step + 1) % length);
    assert(!memcmp(untouched, &before_other, sizeof before_other));
    writes++;
    printf("PASS actual recording: %s writes %s step=%d note=%u; other bass unchanged\n",
           label, PART_N[ui.part], step + 1, destination->step[step].note);
    record_feedback(label);
}

int main(void)
{
    boot();
    proj.set.bt = PROJ_BT_SMC_CENTRAL;
    smc_ble_link(1);
    smc_poll();
    memset(wire_led, 0xFF, sizeof wire_led);
    record_feedback("boot, recording off");

    /* Panel REC must report the real destination even before any SMC REC. */
    panel_button(B_EDIT);
    panel_select(PART_303A);
    panel_button(B_SEQ); /* recording onsets belong to the visible SEQ page */
    assert(ui.view == V_SEQ);
    panel_button(B_REC);
    record_note("panel REC on 303A", 0);

    /* SMC SELECT changes the actual recorder while REC remains enabled. */
    smc_press(24 + display_position[PART_303B]);
    assert(ui.view == V_PART); /* SMC SELECT intentionally opens EDIT */
    panel_button(B_SEQ);      /* return to SEQ to make a pattern write */
    record_note("SMC SELECT changes active recorder to 303B", 2);
    smc_press(0x5F);
    assert(!ui.rec);
    record_feedback("SMC global REC off");

    /* Conversely, panel selection must replace the target of SMC-started REC. */
    smc_press(display_position[PART_303A]);
    record_note("SMC strip REC on 303A", 4);
    panel_select(PART_303B);
    record_note("panel selection changes active recorder to 303B", 5);
    panel_button(B_REC);
    assert(!ui.rec);
    record_feedback("panel REC off");

    printf("%s: %u real pattern writes, %u emitted Record projections, %u failures\n",
           failures ? "FAIL" : "PASS", writes, projections, failures);
    return failures ? 1 : 0;
}
